namespace sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Models;

public class Shipment
{
    public required string TrackingNumber { get; set; }
    public required string Status { get; set; }
    public required string Location { get; set; }
    public DateTimeOffset? EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

public class StatusUpdate
{
    public required string Description { get; set; }
    public required string Location { get; set; }
    public DateTimeOffset Timestamp { get; set; }
}

using sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Models;

namespace sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Models;

namespace sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Services;

public class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Models;
using sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Services;

namespace sv_9cf3fb11026540d7b89e0b38dbe319f2.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 7, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "New York, NY", Timestamp = new DateTimeOffset(2026, 6, 1, 9, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Arrived at sorting facility", Location = "Philadelphia, PA", Timestamp = new DateTimeOffset(2026, 6, 2, 14, 30, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Departed facility", Location = "Philadelphia, PA", Timestamp = new DateTimeOffset(2026, 6, 2, 22, 15, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "In transit", Location = "Chicago, IL", Timestamp = new DateTimeOffset(2026, 6, 3, 11, 45, 0, TimeSpan.Zero) }
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 3, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Seattle, WA", Timestamp = new DateTimeOffset(2026, 5, 30, 8, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "In transit", Location = "Portland, OR", Timestamp = new DateTimeOffset(2026, 5, 31, 16, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Out for delivery", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 6, 2, 7, 30, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Delivered", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 6, 2, 14, 12, 0, TimeSpan.Zero) }
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Processing",
            Location = "Miami, FL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 10, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Label created", Location = "Miami, FL", Timestamp = new DateTimeOffset(2026, 6, 3, 10, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Awaiting carrier pickup", Location = "Miami, FL", Timestamp = new DateTimeOffset(2026, 6, 3, 10, 5, 0, TimeSpan.Zero) }
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Models
@using sv_9cf3fb11026540d7b89e0b38dbe319f2.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<TrackShipment> Logger
@implements IDisposable

<PageTitle>Track Shipment @TrackingNumber</PageTitle>

<h2>Shipment Tracking</h2>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment details for <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mb-4">
        <div class="card-header">
            <strong>@_shipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-4">Status</dt>
                <dd class="col-sm-8">@_shipment.Status</dd>

                <dt class="col-sm-4">Current Location</dt>
                <dd class="col-sm-8">@_shipment.Location</dd>

                <dt class="col-sm-4">Estimated Delivery</dt>
                <dd class="col-sm-8">
                    @(_shipment.EstimatedDelivery?.ToString("f") ?? "N/A")
                </dd>
            </dl>
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h4>Status History</h4>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date &amp; Time</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = "";

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override Task OnParametersSetAsync() => LoadShipmentAsync();

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — silently stop.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "HTTP timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

